package io.github.diodeme.ji.relay;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.relay.protocol.RelayProtocol;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Optional;
import java.util.Set;
import org.junit.jupiter.api.Test;

final class RelayRouterTest {
    private static final Instant NOW = Instant.parse("2026-09-05T12:00:00Z");

    @Test
    void forwardsOpaqueBytesWithoutSessionStateAndEnforcesAuthorizationAndQuota() {
        var store = new MemoryRelayMetadataStore();
        byte[] key = [REDACTED_CREDENTIAL] byte[32];
        store.saveDevice(new RelayMetadataStore.Device("tenant-1", "device-1", key, Set.of(), NOW, Optional.empty()));
        store.saveGrant(new RelayMetadataStore.Grant("tenant-1", "host-1", "device-1",
                Set.of("host:request"), NOW));
        var host = new Endpoint();
        var client = new Endpoint();
        var router = new RelayRouter(store, Clock.fixed(NOW, ZoneOffset.UTC),
                new RelayRouter.Quotas(64, 96, 1));
        router.registerHost("tenant-1", "host-1", key, 1, RelayProtocol.RELEASE_VERSION, host);
        router.open("tenant-1", "route-1", "host-1", "device-1", client);
        byte[] frame = new byte[] { 1, 2, 3, 4 };
        router.clientFrame("tenant-1", "route-1", frame);
        router.hostFrame("tenant-1", "route-1", frame);
        assertArrayEquals(frame, host.frames.getFirst());
        assertArrayEquals(frame, client.frames.getFirst());
        assertThrows(RelayRouter.RelayRoutingException.class,
                () -> router.clientFrame("tenant-2", "route-1", frame));
        assertEquals("relay.quota_exceeded", assertThrows(RelayRouter.RelayRoutingException.class,
                () -> router.clientFrame("tenant-1", "route-1", new byte[93])).code());
    }

    @Test
    void versionMismatchReturnsStructuredUpgradeRequirement() {
        var router = new RelayRouter(new MemoryRelayMetadataStore(), Clock.fixed(NOW, ZoneOffset.UTC),
                RelayRouter.Quotas.defaults());
        var failure = assertThrows(RelayRouter.RelayRoutingException.class,
                () -> router.registerHost("tenant-1", "host-1", new byte[32], 7, "7.0", new Endpoint()));
        assertEquals("protocol.upgrade_required", failure.code());
    }

    private static final class Endpoint implements RelayRouter.OpaqueEndpoint {
        private final ArrayList<byte[]> frames = new ArrayList<>();
        @Override public void send(byte[] frame) { frames.add(frame); }
        @Override public void close(String reason) {}
    }
}
